async (page) => {
  const r = await page.request.get('http://localhost:3000/rest/admin/application-version');
  const p = await page.request.get('http://localhost:3000/api/Products');
  const prods = (await p.json()).data.filter(x => /Eggfruit|Raspberry|Apple Juice|Carrot/.test(x.name)).map(x => [x.id, x.name, x.price, x.limitPerUser]);
  return { date: r.headers()['date'], v: await r.text(), prods, snap: await page.locator('body').ariaSnapshot() };
}

