async (page) => {
  const base = 'http://localhost:3000';
  const email = `explore-${Date.now()}@example.test`, password = 'Passw0rd!x';
  const reg = await page.request.post(base + '/api/Users', { data: { email, password, passwordRepeat: password, securityQuestion: { id: 1 }, securityAnswer: 'x' } });
  const login = await (await page.request.post(base + '/rest/user/login', { data: { email, password } })).json();
  const token = login.authentication.token, bid = login.authentication.bid;
  const h = { Authorization: 'Bearer ' + token };
  const a = await page.request.post(base + '/api/Addresss', { headers: h, data: { country: 'Ukraine', fullName: 'Test Customer', mobileNum: 501234567, zipCode: '01001', streetAddress: '1 Khreshchatyk Street', city: 'Kyiv', state: 'Kyiv' } });
  const c = await page.request.post(base + '/api/Cards', { headers: h, data: { fullName: 'Test Customer', cardNum: 4111111111111111, expMonth: 12, expYear: 2090 } });
  const card = (await c.json()).data;
  const w = await page.request.put(base + '/rest/wallet/balance', { headers: h, data: { balance: 5, paymentId: card.id } });
  const bi = await page.request.post(base + '/api/BasketItems', { headers: h, data: { ProductId: 3, BasketId: String(bid), quantity: 2 } });
  await page.context().addCookies([{ name: 'cookieconsent_status', value: 'dismiss', url: base }, { name: 'token', value: token, url: base }]);
  await page.evaluate(([t, b]) => { localStorage.setItem('token', t); sessionStorage.setItem('bid', b); }, [token, String(bid)]);
  await page.goto(base + '/#/basket'); await page.waitForTimeout(1500);
  const basket = await page.locator('body').ariaSnapshot();
  const basketHtml = await page.locator('mat-table, mat-row').first().evaluate(e => e.outerHTML.slice(0, 3000));
  globalThis.__ex = { email, password, token, bid };
  return { reg: reg.status(), a: a.status(), w: [w.status(), await w.text()], bi: [bi.status(), await bi.text()], basket, basketHtml };
}

