import type { APIRequestContext } from '@playwright/test';
import * as z85 from 'z85';

const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];

/**
 * Coupon code = Z85 encoding of `<MMM><YY>-<NN>` (see test-cases/README.md).
 * `monthOffset` 0 is the month of `date`, -1 is the previous month.
 */
export function couponCode(date: Date, discountPercent: number, monthOffset = 0): string {
  const month = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + monthOffset, 1));
  const yy = String(month.getUTCFullYear() % 100).padStart(2, '0');
  const nn = String(discountPercent).padStart(2, '0');
  const code = z85.encode(`${MONTHS[month.getUTCMonth()]}${yy}-${nn}`);
  if (!code) throw new Error('Z85 encoding failed');
  return code;
}

/** The date of the machine that runs the app, from the HTTP `Date` header. */
export async function serverDate(request: APIRequestContext): Promise<Date> {
  const response = await request.get('/rest/admin/application-version');
  const header = response.headers()['date'];
  return header ? new Date(header) : new Date();
}

