import { expect, type APIRequestContext } from '@playwright/test';
import { savedAddress, savedCard } from './test-data';

export interface Credentials {
  email: string;
  password: string;
}

export interface Session {
  token: string;
  basketId: number;
}

/** REST client for test preconditions. It does not replace UI steps. */
export class ShopApi {
  private session?: Session;

  constructor(private readonly request: APIRequestContext) {}

  async registerCustomer({ email, password }: Credentials): Promise<void> {
    const response = await this.request.post('/api/Users', {
      data: {
        email,
        password,
        passwordRepeat: password,
        securityQuestion: { id: 1 },
        securityAnswer: 'test',
      },
    });
    expect(response.status(), await response.text()).toBe(201);
  }

  async login({ email, password }: Credentials): Promise<Session> {
    const response = await this.request.post('/rest/user/login', { data: { email, password } });
    expect(response.status(), await response.text()).toBe(200);
    const { authentication } = await response.json();
    this.session = { token: authentication.token, basketId: authentication.bid };
    return this.session;
  }

  async addSavedAddress(): Promise<void> {
    await this.post('/api/Addresss', savedAddress);
  }

  async addSavedCard(): Promise<number> {
    const card = await this.post('/api/Cards', savedCard);
    return card.id;
  }

  async addToBasket(productName: string, quantity: number): Promise<void> {
    const productId = await this.productId(productName);
    await this.post('/api/BasketItems', {
      ProductId: productId,
      BasketId: String(this.requireSession().basketId),
      quantity,
    });
  }

  async topUpWallet(amount: number, cardId: number): Promise<void> {
    const response = await this.request.put('/rest/wallet/balance', {
      headers: this.authHeaders(),
      data: { balance: amount, paymentId: cardId },
    });
    expect(response.status(), await response.text()).toBe(200);
  }

  private async productId(name: string): Promise<number> {
    const response = await this.request.get('/api/Products');
    expect(response.ok()).toBeTruthy();
    const { data } = await response.json();
    const product = data.find((p: { name: string }) => p.name === name);
    if (!product) throw new Error(`Product not found: ${name}`);
    return product.id;
  }

  private async post(url: string, data: unknown) {
    const response = await this.request.post(url, { headers: this.authHeaders(), data });
    expect(response.ok(), `${url}: ${await response.text()}`).toBeTruthy();
    return (await response.json()).data;
  }

  private authHeaders() {
