import { test as base, type Page } from '@playwright/test';
import { ShopApi, type Credentials, type Session } from './api';
import { uniqueEmail } from './test-data';

export interface Customer extends Credentials {
  api: ShopApi;
  session: Session;
}

interface Fixtures {
  /** A new, registered customer account. The API client is logged in. */
  customer: Customer;
}

export const test = base.extend<Fixtures>({
  page: async ({ page, baseURL }, use) => {
    // The cookie hides the cookie banner (test-cases/README.md).
    await page.context().addCookies([{ name: 'cookieconsent_status', value: 'dismiss', url: baseURL! }]);
    await use(page);
  },

  customer: async ({ request }, use, testInfo) => {
    const prefix = testInfo.titlePath.at(-1)!.match(/^TC-\d+/)?.[0].toLowerCase() ?? 'customer';
    const credentials = { email: uniqueEmail(prefix), password: `Passw0rd!${prefix}` };
    const api = new ShopApi(request);
    await api.registerCustomer(credentials);
    const session = await api.login(credentials);
    await use({ ...credentials, api, session });
  },
});

/**
 * Logs the customer in the browser with the API token, the same way the login page does.
 * Call it after all API preconditions so the app loads the current basket and wallet.
 */
export async function signInBrowser(page: Page, customer: Customer, path = '/#/search'): Promise<void> {
  const { token, basketId } = customer.session;
  await page.context().addCookies([{ name: 'token', value: token, url: page.context()['_options']?.baseURL ?? 'http://localhost:3000' }]);
  await page.addInitScript(
    ([t, bid]) => {
      if (!window.localStorage.getItem('token')) window.localStorage.setItem('token', t);
      if (!window.sessionStorage.getItem('bid')) window.sessionStorage.setItem('bid', bid);
    },
    [token, String(basketId)] as const,
  );
  await page.goto(path);
}

export { expect } from '@playwright/test';

