import { expect, type Locator, type Page } from '@playwright/test';

/** Top bar: account menu and basket button with the item counter. */
export class NavBar {
  readonly accountButton: Locator;
  readonly basketButton: Locator;
  readonly accountMenu: Locator;

  constructor(private readonly page: Page) {
    this.accountButton = page.getByRole('button', { name: 'Show/hide account menu' });
    this.basketButton = page.getByRole('button', { name: 'Show the shopping cart' });
    this.accountMenu = page.getByRole('menu').first();
  }

  async expectBasketCount(count: number): Promise<void> {
    await expect(this.basketButton).toHaveText(new RegExp(`Your Basket\\s*${count}\\s*$`));
  }

  async openBasket(): Promise<void> {
    await this.basketButton.click();
    await expect(this.page).toHaveURL(/#\/basket$/);
  }

  async openAccountMenu(): Promise<void> {
    await this.accountButton.click();
    await expect(this.accountMenu).toBeVisible();
  }

  async closeAccountMenu(): Promise<void> {
    await this.page.keyboard.press('Escape');
    await expect(this.page.getByRole('menu')).toHaveCount(0);
  }

  menuItem(name: string | RegExp): Locator {
    return this.page.getByRole('menuitem').filter({ hasText: name });
  }

  async openOrderHistory(): Promise<void> {
    await this.openOrdersAndPaymentItem('Order History');
    await expect(this.page).toHaveURL(/#\/order-history$/);
  }

  async openDigitalWallet(): Promise<void> {
    await this.openOrdersAndPaymentItem('Digital Wallet');
    await expect(this.page).toHaveURL(/#\/wallet$/);
  }

  private async openOrdersAndPaymentItem(item: string): Promise<void> {
    await this.openAccountMenu();
    await this.menuItem('Orders & Payment').click();
    await this.menuItem(item).click();
  }
}

