import { expect, type Locator, type Page } from '@playwright/test';

/** Snack bar messages ("Placed ... into basket.", purchase limit errors). */
export class Notifications {
  readonly messages: Locator;
  readonly errors: Locator;

  constructor(page: Page) {
    this.messages = page.locator('simple-snack-bar');
    this.errors = page.locator('mat-snack-bar-container.errorBar');
  }

  message(text: string): Locator {
    return this.messages.filter({ hasText: text });
  }

  async expectMessage(text: string): Promise<void> {
    await expect(this.message(text).first()).toBeVisible();
  }

  async expectNoError(): Promise<void> {
    await expect(this.errors).toHaveCount(0);
  }

  /** Close all open messages, so the next check sees only new ones. */
  async dismissAll(): Promise<void> {
    for (const button of await this.messages.getByRole('button', { name: 'X' }).all()) {
      await button.click().catch(() => undefined);
    }
    await expect(this.messages).toHaveCount(0);
  }
}

