import { expect, type Locator, type Page } from '@playwright/test';

/** Basket `/#/basket`. */
export class BasketPage {
  readonly rows: Locator;
  readonly totalPrice: Locator;
  readonly checkoutButton: Locator;

  constructor(private readonly page: Page) {
    const basket = page.locator('app-basket');
    this.rows = basket.locator('mat-row');
    this.totalPrice = basket.getByText(/^Total Price:/);
    this.checkoutButton = basket.getByRole('button', { name: 'Checkout' });
  }

  async open(): Promise<void> {
    await this.page.goto('/#/basket');
    await expect(this.page.getByRole('heading', { name: /^Your Basket/ })).toBeVisible();
  }

  row(productName: string): Locator {
    return this.rows.filter({ has: this.page.locator('.mat-column-product', { hasText: productName }) });
  }

  quantity(productName: string): Locator {
    return this.row(productName).locator('.mat-column-quantity');
  }

  price(productName: string): Locator {
    return this.row(productName).locator('.mat-column-price');
  }

  async expectRow(productName: string, quantity: number, price?: string): Promise<void> {
    await expect(this.row(productName)).toHaveCount(1);
    await expect(this.quantity(productName)).toHaveText(String(quantity));
    if (price) await expect(this.price(productName)).toHaveText(price);
  }

  async expectTotal(total: string): Promise<void> {
    await expect(this.totalPrice).toHaveText(`Total Price: ${total}`);
  }

  async increase(productName: string): Promise<void> {
    await this.changeQuantity(this.quantity(productName).getByRole('button').last());
  }

  async decrease(productName: string): Promise<void> {
    await this.changeQuantity(this.quantity(productName).getByRole('button').first());
  }

  async remove(productName: string): Promise<void> {
    const response = this.page.waitForResponse(
      (r) => r.url().includes('/api/BasketItems/') && r.request().method() === 'DELETE',
    );
    await this.row(productName).locator('.mat-column-remove').getByRole('button').click();
    await response;
  }

  async checkout(): Promise<void> {
    await this.checkoutButton.click();
    await expect(this.page).toHaveURL(/#\/address\/select$/);
  }

  /** Clicks a plus or minus button and waits until the basket is loaded again. */
  private async changeQuantity(button: Locator): Promise<void> {
    const update = this.page.waitForResponse(
      (r) => r.url().includes('/api/BasketItems/') && r.request().method() === 'PUT',
    );
    await button.click();
    if ((await update).ok()) {
      await this.page.waitForResponse((r) => /\/rest\/basket\/\d+$/.test(r.url()));
    }
  }
}

