import { expect, test } from './support/fixtures';
import { Shop } from './pages/shop';

test('TC-01: Login with a valid and an invalid password', async ({ page, customer }) => {
  const shop = new Shop(page);
  const wrongPassword = `${customer.password}x`;

  await test.step('1. Open the login page', async () => {
    await shop.login.open();
    await expect(shop.login.heading).toHaveText('Login');
    await expect(page.locator('app-login').getByText('Email', { exact: true })).toBeVisible();
    await expect(page.locator('app-login').getByText('Password', { exact: true })).toBeVisible();
    await expect(shop.login.emailInput).toBeVisible();
    await expect(shop.login.passwordInput).toBeVisible();
    await expect(shop.login.loginButton).toHaveText('Log in');
  });

  await test.step('2. Log in with the wrong password', async () => {
    await shop.login.login(customer.email, wrongPassword);
    await expect(shop.login.error).toHaveText('Invalid email or password.');
    await expect(page).toHaveURL(/#\/login$/);
  });

  await test.step('3. Account menu shows Login and no email', async () => {
    await shop.navBar.openAccountMenu();
    await expect(shop.navBar.menuItem(/^\s*Login\s*$/)).toBeVisible();
    await expect(shop.navBar.accountMenu).not.toContainText(customer.email);
  });

  await test.step('4. Log in with the correct password', async () => {
    await shop.navBar.closeAccountMenu();
    await shop.login.login(customer.email, customer.password);
    await expect(page).toHaveURL(/#\/search$/);
  });

  await test.step('5. Account menu shows the email and Logout', async () => {
    await shop.navBar.openAccountMenu();
    await expect(shop.navBar.menuItem(customer.email)).toBeVisible();
    await expect(shop.navBar.menuItem('Logout')).toBeVisible();
  });
});

