import { expect, signInBrowser, test } from './support/fixtures';
import { products } from './support/test-data';
import { Shop } from './pages/shop';

test('TC-02: Add a product to the basket', async ({ page, customer }) => {
  const shop = new Shop(page);
  const product = products.eggfruitJuice;
  await signInBrowser(page, customer);

  await test.step('1. Open the product list', async () => {
    await shop.search.open();
    await expect(shop.search.productCard(product.name)).toContainText(product.name);
    await expect(shop.search.productPrice(product.name)).toHaveText(product.price);
    await expect(shop.search.addToBasketButton(product.name)).toBeVisible();
    await shop.navBar.expectBasketCount(0);
  });

  await test.step('2. Click Add to Basket', async () => {
    await shop.search.addToBasket(product.name);
    await shop.notifications.expectMessage(`Placed ${product.name} into basket.`);
    await shop.navBar.expectBasketCount(1);
  });

  await test.step('3. Open the basket with Your Basket', async () => {
    await shop.navBar.openBasket();
    await expect(shop.basket.rows).toHaveCount(1);
    await shop.basket.expectRow(product.name, 1, product.price);
  });

  await test.step('4. Read the basket total', async () => {
    await shop.basket.expectTotal('8.99¤');
  });
});

