import { expect, signInBrowser, test } from './support/fixtures';
import { products } from './support/test-data';
import { Shop } from './pages/shop';

test('TC-03: Change the quantity and remove a product in the basket', async ({ page, customer }) => {
  const shop = new Shop(page);
  const a = products.raspberryJuice;
  const b = products.eggfruitJuice;
  await customer.api.addToBasket(a.name, 1);
  await customer.api.addToBasket(b.name, 1);
  await signInBrowser(page, customer, '/#/basket');

  await test.step('1. Open the basket', async () => {
    await shop.basket.open();
    await expect(shop.basket.rows).toHaveCount(2);
    await shop.basket.expectRow(a.name, 1);
    await shop.basket.expectRow(b.name, 1);
    await shop.basket.expectTotal('13.98¤');
    await shop.navBar.expectBasketCount(2);
  });

  await test.step('2. Plus on product A', async () => {
    await shop.basket.increase(a.name);
    await shop.basket.expectRow(a.name, 2);
    await shop.basket.expectTotal('18.97¤');
    await shop.navBar.expectBasketCount(3);
  });

  await test.step('3. Minus on product A', async () => {
    await shop.basket.decrease(a.name);
    await shop.basket.expectRow(a.name, 1);
    await shop.basket.expectTotal('13.98¤');
    await shop.navBar.expectBasketCount(2);
  });

  await test.step('4. Minus on product A again', async () => {
    await shop.basket.decrease(a.name);
    await shop.basket.expectRow(a.name, 1);
    await shop.basket.expectTotal('13.98¤');
  });

  await test.step('5. Trash on product A', async () => {
    await shop.basket.remove(a.name);
    await expect(shop.basket.row(a.name)).toHaveCount(0);
    await shop.basket.expectRow(b.name, 1);
    await shop.basket.expectTotal('8.99¤');
    await shop.navBar.expectBasketCount(1);
  });
});

