import { expect, signInBrowser, test } from './support/fixtures';
import { products } from './support/test-data';
import { Shop } from './pages/shop';

test('TC-04: Purchase limit for one product', async ({ page, customer }) => {
  const shop = new Shop(page);
  const product = products.appleJuice;
  const limitError = 'You can order only up to 5 items of this product.';
  await signInBrowser(page, customer);

  await test.step('1. Add the product from the product list', async () => {
    await shop.search.open();
    await shop.search.addToBasket(product.name);
    await shop.notifications.expectMessage(`Placed ${product.name} into basket.`);
    await shop.navBar.expectBasketCount(1);
  });

  await test.step('2. Plus until the quantity is 5', async () => {
    await shop.basket.open();
    await shop.notifications.dismissAll();
    for (let quantity = 2; quantity <= 5; quantity++) {
      await shop.basket.increase(product.name);
      await shop.basket.expectRow(product.name, quantity);
    }
    await shop.basket.expectTotal('9.95¤');
    await shop.notifications.expectNoError();
  });

  await test.step('3. Plus one more time', async () => {
    await shop.basket.increase(product.name);
    await shop.notifications.expectMessage(limitError);
  });

  await test.step('4. Read the basket', async () => {
    await shop.basket.expectRow(product.name, 5);
    await shop.basket.expectTotal('9.95¤');
    await shop.navBar.expectBasketCount(5);
  });

  await test.step('5. Add the product from the product list again', async () => {
    await shop.notifications.dismissAll();
    await shop.search.open();
    await shop.search.addToBasket(product.name);
    await shop.notifications.expectMessage(limitError);
    await shop.navBar.expectBasketCount(5);
  });
});

