import { couponCode, serverDate } from './support/coupon';
import { deliveryMethods, products, savedAddress } from './support/test-data';
import { Shop } from './pages/shop';

test('TC-07: Order with a card, from basket to order history', async ({ page, customer, request }) => {
  const shop = new Shop(page);
  const a = products.eggfruitJuice;
  const b = products.carrotJuice;
  const coupon = couponCode(await serverDate(request), 10);
  const expectedTotals = {
    Items: '20.97¤',
    Delivery: '0.99¤',
    Promotion: '2.10¤',
    'Total Price': '19.86¤',
  };
  let orderId = '';
  await customer.api.addSavedAddress();
  await customer.api.addSavedCard();
  await signInBrowser(page, customer);

  await test.step('1. Add product A two times and product B one time', async () => {
    await shop.search.open();
    await shop.search.addToBasket(a.name);
    await shop.navBar.expectBasketCount(1);
    await shop.search.addToBasket(a.name);
    await shop.navBar.expectBasketCount(2);
    await shop.search.addToBasket(b.name);
    await shop.navBar.expectBasketCount(3);
  });

  await test.step('2. Open the basket', async () => {
    await shop.basket.open();
    await shop.basket.expectRow(a.name, 2);
    await shop.basket.expectRow(b.name, 1);
    await shop.basket.expectTotal('20.97¤');
  });

  await test.step('3. Checkout and select the saved address', async () => {
    await shop.basket.checkout();
    await shop.addressSelect.selectAndContinue(savedAddress.fullName);
    await expect(shop.deliveryMethod.heading).toBeVisible();
  });

  await test.step('4. Select One Day Delivery', async () => {
    await shop.deliveryMethod.selectAndContinue(deliveryMethods.oneDay.name);
    await expect(shop.payment.heading).toBeVisible();
  });

  await test.step('5. Redeem the coupon', async () => {
    await shop.payment.openCouponPanel();
    await shop.payment.redeemCoupon(coupon);
    await expect(shop.payment.root).toContainText('Your discount of 10% will be applied during checkout.');
  });

  await test.step('6. Select the saved card', async () => {
    await shop.payment.selectCardAndContinue('1111');
    await expect(shop.orderSummary.root).toContainText(savedAddress.fullName);
    await expect(shop.orderSummary.root).toContainText(savedAddress.streetAddress);
    await expect(shop.orderSummary.root).toContainText('Card ending in 1111');
    await shop.orderSummary.expectTotals(expectedTotals);
  });

  await test.step('7. Place the order', async () => {
    orderId = await shop.orderSummary.placeOrder();
    await expect(shop.orderCompletion.heading).toBeVisible();
  });

  await test.step('8. Read the order summary on the confirmation page', async () => {
    await expect(shop.orderCompletion.productQuantity(a.name)).toHaveText('2');
    await expect(shop.orderCompletion.productQuantity(b.name)).toHaveText('1');
    await shop.orderCompletion.expectTotals(expectedTotals);
  });

  await test.step('9. The basket is empty', async () => {
    await shop.navBar.expectBasketCount(0);
    await shop.basket.open();
    await expect(shop.basket.rows).toHaveCount(0);
    await expect(shop.basket.checkoutButton).toBeDisabled();
  });

  await test.step('10. Order History shows the order', async () => {
    await shop.navBar.openOrderHistory();
    await expect(shop.orderHistory.orders).toHaveCount(1);
    const order = shop.orderHistory.order(orderId);
    await expect(order).toBeVisible();
    await expect(shop.orderHistory.orderField(order, 'Total Price')).toHaveText('19.86¤');
    await expect(shop.orderHistory.productQuantity(order, a.name)).toHaveText('2');
    await expect(shop.orderHistory.productQuantity(order, b.name)).toHaveText('1');
  });
});

