import { expect, test } from './support/fixtures';
import { Shop } from './pages/shop';

test('TC-01: Login with a valid and an invalid password', async ({ page, customer }) => {
  const shop = new Shop(page);
  const wrongPassword = `${customer.password}x`;

  await test.step('1. Open the login page', async () => {
    await shop.login.open();
    await expect(shop.login.heading).toHaveText('Login');
    await expect(page.locator('app-login').getByText('Email', { exact: true })).toBeVisible();
    await expect(page.locator('app-login').getByText('Password', { exact: true })).toBeVisible();
    await expect(shop.login.emailInput).toBeVisible();
    await expect(shop.login.passwordInput).toBeVisible();
    await expect(shop.login.loginButton).toHaveText('Log in');
  });

  await test.step('2. Log in with the wrong password', async () => {
    await shop.login.login(customer.email, wrongPassword);
    await expect(shop.login.error).toHaveText('Invalid email or password.');
    await expect(page).toHaveURL(/#\/login$/);
  });

  await test.step('3. Account menu shows Login and no email', async () => {
    await shop.navBar.openAccountMenu();
    await expect(shop.navBar.menuItem(/^\s*Login\s*$/)).toBeVisible();
    await expect(shop.navBar.accountMenu).not.toContainText(customer.email);
  });

  await test.step('4. Log in with the correct password', async () => {
    await shop.navBar.closeAccountMenu();
    await shop.login.login(customer.email, customer.password);
    await expect(page).toHaveURL(/#\/search$/);
  });

  await test.step('5. Account menu shows the email and Logout', async () => {
    await shop.navBar.openAccountMenu();
    await expect(shop.navBar.menuItem(customer.email)).toBeVisible();
    await expect(shop.navBar.menuItem('Logout')).toBeVisible();
  });
});

import { expect, type Locator, type Page } from '@playwright/test';

/** `Select an address` `/#/address/select`. */
export class AddressSelectPage {
  readonly heading: Locator;
  readonly continueButton: Locator;

  constructor(private readonly page: Page) {
    this.heading = page.getByRole('heading', { name: 'Select an address' });
    this.continueButton = page.getByRole('button', { name: 'Proceed to payment selection' });
  }

  addressRow(name: string): Locator {
    return this.page.getByRole('row').filter({ hasText: name });
  }

  async selectAndContinue(name: string): Promise<void> {
    await this.addressRow(name).getByRole('radio').click();
    await this.continueButton.click();
    await expect(this.page).toHaveURL(/#\/delivery-method$/);
  }
}

/** `Choose a delivery speed` `/#/delivery-method`. */
export class DeliveryMethodPage {
  readonly heading: Locator;
  readonly continueButton: Locator;

  constructor(private readonly page: Page) {
    this.heading = page.getByRole('heading', { name: 'Choose a delivery speed' });
    this.continueButton = page.getByRole('button', { name: 'Proceed to delivery method selection' });
  }

  methodRow(name: string): Locator {
    return this.page.getByRole('row').filter({ hasText: name });
  }

  methodPrice(name: string): Locator {
    return this.methodRow(name).getByRole('cell').nth(2);
  }

  async selectAndContinue(name: string): Promise<void> {
    await this.methodRow(name).getByRole('radio').click();
    await this.continueButton.click();
    await expect(this.page).toHaveURL(/#\/payment\/shop$/);
  }
}

/** `My Payment Options` `/#/payment/shop`. */
export class PaymentPage {
  readonly heading: Locator;
  readonly root: Locator;
  readonly couponPanel: Locator;
  readonly couponInput: Locator;
  readonly redeemButton: Locator;
  readonly continueButton: Locator;

  constructor(private readonly page: Page) {
    this.root = page.locator('app-payment');
    this.heading = this.root.getByRole('heading', { name: 'My Payment Options' });
    this.couponPanel = this.root.getByRole('button', { name: /^Add a coupon/ });
    this.couponInput = this.root.getByRole('textbox', { name: 'Coupon' });
    this.redeemButton = this.root.getByRole('button', { name: 'Redeem' });
    this.continueButton = this.root.getByRole('button', { name: 'Proceed to review' });
  }

  cardRow(lastDigits: string): Locator {
    return this.root.getByRole('row').filter({ hasText: `************${lastDigits}` });
  }

  walletPayButton(amount: string): Locator {
    return this.root.getByRole('button', { name: `Pay ${amount}` });
  }

  async expectWalletBalance(balance: string): Promise<void> {
    await expect(this.root).toContainText(new RegExp(`Wallet Balance\\s*${balance.replace('.', '\\.')}`));
  }

  async openCouponPanel(): Promise<void> {
    await this.couponPanel.click();
    await expect(this.couponInput).toBeVisible();
  }

  /** Types the code, clicks `Redeem` and waits for the answer of the server. */
  async redeemCoupon(code: string): Promise<void> {
    await this.couponInput.fill(code);
    const response = this.page.waitForResponse((r) => r.url().includes('/coupon/'));
    await this.redeemButton.click();
    await response;
  }

  async selectCardAndContinue(lastDigits: string): Promise<void> {
    await this.cardRow(lastDigits).getByRole('radio').click();
    await this.continueButton.click();
    await expect(this.page).toHaveURL(/#\/order-summary$/);
  }

  async payWithWallet(amount: string): Promise<void> {
    await this.walletPayButton(amount).click();
    await expect(this.page).toHaveURL(/#\/order-summary$/);
  }
}

/** `Order Summary` `/#/order-summary`, the last page before the order is placed. */
export class OrderSummaryPage {
  readonly root: Locator;
  readonly placeOrderButton: Locator;

  constructor(private readonly page: Page) {
    this.root = page.locator('app-order-summary');
    this.placeOrderButton = this.root.getByRole('button', { name: 'Complete your purchase' });
  }

  summaryValue(label: string): Locator {
    return this.root.locator('.order-summary + table tr').filter({ hasText: label }).locator('td').last();
  }

  async expectTotals(totals: Record<string, string>): Promise<void> {
    await expect(this.root.getByText('Order Summary', { exact: true })).toBeVisible();
    for (const [label, value] of Object.entries(totals)) {
      await expect(this.summaryValue(label), label).toHaveText(value);
    }
  }

  async placeOrder(): Promise<string> {
    await expect(this.placeOrderButton).toHaveText('Place your order and pay');
    await this.placeOrderButton.click();
    await expect(this.page).toHaveURL(/#\/order-completion\/[\w-]+$/);
    return this.page.url().split('/').pop()!;
  }
}

/** Confirmation page `/#/order-completion/<order ID>`. */
export class OrderCompletionPage {
  readonly root: Locator;
  readonly heading: Locator;

  constructor(private readonly page: Page) {
    this.root = page.locator('app-order-completion');
    this.heading = this.root.getByRole('heading', { name: 'Thank you for your purchase!' });
  }

  productQuantity(productName: string): Locator {
    return this.root.getByRole('row').filter({ hasText: productName }).getByRole('cell').nth(2);
  }

  /**
   * The summary has one cell with the labels and one cell with the values,
   * each holds a table with one row per line.
   */
  async totals(): Promise<Record<string, string>> {
    return this.root.locator('td:has(> table)').first().evaluate((labelCell) => {
      const valueCell = labelCell.nextElementSibling!;
      const texts = (cell: Element) =>
        Array.from(cell.querySelectorAll('tr')).map((tr) => tr.textContent!.trim());
      const labels = texts(labelCell);
      const values = texts(valueCell);
      return Object.fromEntries(labels.map((label, i) => [label, values[i]]));
    });
  }

  async expectTotals(expected: Record<string, string>): Promise<void> {
    await expect.poll(() => this.totals()).toEqual(expect.objectContaining(expected));
  }
}

/** `Order History` `/#/order-history`. */
export class OrderHistoryPage {
  readonly root: Locator;
  readonly orders: Locator;

  constructor(page: Page) {
    this.root = page.locator('app-order-history');
    this.orders = this.root.locator('.table-container');
  }

  order(orderId: string): Locator {
    return this.orders.filter({ hasText: `#${orderId}` });
  }

  /** Value of a header field of an order, for example `Total Price` or `Bonus`. */
  orderField(order: Locator, label: string): Locator {
    return order.locator('.col-vertical').filter({ hasText: label }).locator('div').nth(1);
  }

  productQuantity(order: Locator, productName: string): Locator {
    return order.getByRole('row').filter({ hasText: productName }).getByRole('cell').nth(2);
  }
}

/** `Digital Wallet` `/#/wallet`. */
export class WalletPage {
  readonly balance: Locator;

  constructor(page: Page) {
    this.balance = page.locator('app-wallet').getByText('Wallet Balance').locator('xpath=following-sibling::span');
  }
}

