import { expect, type Locator, type Page } from '@playwright/test';

/** Snack bar messages ("Placed ... into basket.", purchase limit errors). */
export class Notifications {
  readonly messages: Locator;
  readonly errors: Locator;

  constructor(page: Page) {
    this.messages = page.locator('simple-snack-bar');
    this.errors = page.locator('mat-snack-bar-container.errorBar');
  }

  message(text: string): Locator {
    return this.messages.filter({ hasText: text });
  }

  async expectMessage(text: string): Promise<void> {
    await expect(this.message(text).first()).toBeVisible();
  }

  async expectNoError(): Promise<void> {
    await expect(this.errors).toHaveCount(0);
  }

  /** Close all open messages, so the next check sees only new ones. */
  async dismissAll(): Promise<void> {
    for (const button of await this.messages.getByRole('button', { name: 'X' }).all()) {
      await button.click().catch(() => undefined);
    }
    await expect(this.messages).toHaveCount(0);
  }
}

import { expect, test } from './support/fixtures';
import { Shop } from './pages/shop';

test('TC-01: Login with a valid and an invalid password', async ({ page, customer }) => {
  const shop = new Shop(page);
  const wrongPassword = `${customer.password}x`;

  await test.step('1. Open the login page', async () => {
    await shop.login.open();
    await expect(shop.login.heading).toHaveText('Login');
    await expect(page.locator('app-login').getByText('Email', { exact: true })).toBeVisible();
    await expect(page.locator('app-login').getByText('Password', { exact: true })).toBeVisible();
    await expect(shop.login.emailInput).toBeVisible();
    await expect(shop.login.passwordInput).toBeVisible();
    // The button text also holds the name of its icon.
    await expect(shop.login.loginButton).toContainText('Log in');
  });

  await test.step('2. Log in with the wrong password', async () => {
    await shop.login.login(customer.email, wrongPassword);
    await expect(shop.login.error).toHaveText('Invalid email or password.');
    await expect(page).toHaveURL(/#\/login$/);
  });

  await test.step('3. Account menu shows Login and no email', async () => {
    await shop.navBar.openAccountMenu();
    await expect(shop.navBar.menuItem(/^\s*Login\s*$/)).toBeVisible();
    await expect(shop.navBar.accountMenu).not.toContainText(customer.email);
  });

  await test.step('4. Log in with the correct password', async () => {
    await shop.navBar.closeAccountMenu();
    await shop.login.login(customer.email, customer.password);
    await expect(page).toHaveURL(/#\/search$/);
  });

  await test.step('5. Account menu shows the email and Logout', async () => {
    await shop.navBar.openAccountMenu();
    await expect(shop.navBar.menuItem(customer.email)).toBeVisible();
    await expect(shop.navBar.menuItem('Logout')).toBeVisible();
  });
});

import { expect, type Locator, type Page } from '@playwright/test';

/** `Select an address` `/#/address/select`. */
export class AddressSelectPage {
  readonly heading: Locator;
  readonly continueButton: Locator;

  constructor(private readonly page: Page) {
    this.heading = page.getByRole('heading', { name: 'Select an address' });
    this.continueButton = page.getByRole('button', { name: 'Proceed to payment selection' });
  }

  addressRow(name: string): Locator {
    return this.page.getByRole('row').filter({ hasText: name });
  }

  async selectAndContinue(name: string): Promise<void> {
    await this.addressRow(name).getByRole('radio').click();
    await this.continueButton.click();
    await expect(this.page).toHaveURL(/#\/delivery-method$/);
  }
}

